        <option value="leave">Leave</option>
        <option value="other">Other</option>
    </select>

    <label for="details">Details</label>
    <textarea id="details" rows="4"></textarea>

    <label for="documents">Upload Documents</label>
    <input type="file" id="documents" multiple aria-describedby="file-list"/>

    <ul id="file-list" aria-live="polite"></ul>

    <input type="submit" value="Submit" onclick="submitClaim(event)" />
</form>

<div id="confirmation"></div>

<div id="footer-note">MapleSure Insurance — fictional demo application</div>

<script>
    const memberData = {
        "ABC123": "John Doe",
        "XYZ789": "Jane Smith"
    };

    function lookupMember() {
        const memberId = document.getElementById('member-id').value;
        const memberDetailsDiv = document.getElementById('member-details');
        if (memberData[memberId]) {
            memberDetailsDiv.textContent = `Member: ${memberData[memberId]}`;
        } else {
            memberDetailsDiv.textContent = "Member not found.";
        }
    }

    document.getElementById('documents').addEventListener('change', function() {
        const fileList = document.getElementById('file-list');
        fileList.innerHTML = '';
        Array.from(this.files).forEach(file => {
            const li = document.createElement('li');
            li.textContent = file.name;
            fileList.appendChild(li);
        });
    });

    function submitClaim(event) {
        event.preventDefault();
        const referenceNumber = `MS-2026-08-${Math.floor(1000 + Math.random() * 9000)}`;
        document.getElementById('claim-form').style.display = 'none';
        const confirmationDiv = document.getElementById('confirmation');
        confirmationDiv.innerHTML = `<p>Claim submitted successfully. Reference Number: ${referenceNumber}</p><p>Status: Received</p>`;
        confirmationDiv.style.display = 'block';
    }
</script>

</body>
</html>

